package com.grifplot.libros;
import android.content.*;import android.graphics.*;import android.graphics.pdf.*;import android.net.*;import android.os.*;import java.io.*;
final class PdfSession implements AutoCloseable {
 final PdfRenderer renderer;final ParcelFileDescriptor fd;final File temp; final int count;
 PdfSession(Context ctx, String uri)throws Exception{ParcelFileDescriptor descriptor=null;PdfRenderer r=null;File copy=null;try{descriptor=ctx.getContentResolver().openFileDescriptor(Uri.parse(uri),"r");if(descriptor==null)throw new IOException("No se pudo abrir el archivo");try{r=new PdfRenderer(descriptor);}catch(IllegalArgumentException e){descriptor.close();descriptor=null;copy=File.createTempFile("reading", ".pdf",ctx.getCacheDir());try(InputStream in=ctx.getContentResolver().openInputStream(Uri.parse(uri));OutputStream out=new FileOutputStream(copy)){if(in==null)throw new IOException();byte[] b=new byte[65536];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>1024L*1024*1024)throw new IOException("El PDF supera 1 GB");out.write(b,0,n);}}descriptor=ParcelFileDescriptor.open(copy,ParcelFileDescriptor.MODE_READ_ONLY);r=new PdfRenderer(descriptor);}count=r.getPageCount();if(count==0)throw new IOException("El PDF no tiene páginas");renderer=r;fd=descriptor;temp=copy;}catch(Exception e){if(r!=null)r.close();if(descriptor!=null)try{descriptor.close();}catch(Exception ignored){}if(copy!=null)copy.delete();throw e;}}
 synchronized Bitmap render(int index,int width){try(PdfRenderer.Page p=renderer.openPage(index)){int w=Math.max(32,Math.min(3000,width)),h=Math.max(1,(int)((double)w*p.getHeight()/p.getWidth()));if((long)w*h>7000000){double factor=Math.sqrt(7000000.0/(w*(double)h));w=(int)(w*factor);h=(int)(h*factor);}Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);return b;}}
 synchronized Bitmap renderFit(int index,int availableWidth,int availableHeight){try(PdfRenderer.Page p=renderer.openPage(index)){double factor=Math.min(availableWidth/(double)p.getWidth(),availableHeight/(double)p.getHeight());factor=Math.min(factor,1600.0/Math.max(p.getWidth(),p.getHeight()));int w=Math.max(1,(int)Math.round(p.getWidth()*factor)),h=Math.max(1,(int)Math.round(p.getHeight()*factor));Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);b.eraseColor(Color.WHITE);p.render(b,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);return b;}}
 @Override public synchronized void close(){renderer.close();try{fd.close();}catch(IOException ignored){}if(temp!=null)temp.delete();}
}
